// k1w1: retain each asynchronous service result. A void JS call is not an
// acknowledgement; fences must wait for every preceding native operation.
private class Command(
  val operation: String,
  val playerCommand: Boolean,
  val completion: ((SessionResult?, Throwable?) -> Unit)? = null,
  val fence: Boolean = false,
  val block: (MediaController) -> ListenableFuture<SessionResult>?,
) {
  private var completed = false
  fun finish(result: SessionResult?, error: Throwable?) {
    if (completed) return
    completed = true
    completion?.invoke(result, error)
  }
}

