fun awaitReady(complete: (Throwable?) -> Unit) {
  runAfterDestroy {
    val connection = attempt
    when {
      connection == null -> complete(IllegalStateException("Playback controller is not connected"))
      connection.ready -> complete(null)
      else -> readyWaiters.add(complete)
    }
  }
}

