private fun execute(command: Command, mc: MediaController) {
  if (command.playerCommand) playerCommandsPending = true
  try {
    command.block(mc)
  } catch (error: Exception) {
    Log.e("TrackPlayer", "Controller ${command.operation} failed", error)
  }
}

private fun awaitResult(connection: Connection, result: ListenableFuture<SessionResult>, configuring: Boolean, complete: () -> Unit) {
  result.addListener({
    if (attempt === connection) {
      val operation = if (configuring) "configuration" else "awaitPlayerCommands"
      try {
        val code = result.get().resultCode
        if (code == SessionError.ERROR_SESSION_DISCONNECTED) {
          fail("Controller $operation disconnected")
          return@addListener
        }
        check(code == SessionResult.RESULT_SUCCESS) { "Session result: $code" }
      } catch (error: Exception) {
        if (configuring) {
          fail("Controller $operation failed", error)
          return@addListener
        }
        Log.e("TrackPlayer", "Controller $operation failed", error)
      }
      complete()
      commandRunning = false
      drainCommands()
    }
  }, mainExecutor)
}

