private fun execute(command: Command, mc: MediaController) {
  val connection = attempt ?: return
  if (command.playerCommand) playerCommandsPending = true
  try {
    val result = command.block(mc)
    if (result == null) {
      finishCommand(command, null, null)
    } else {
      commandRunning = true
      awaitResult(connection, result, configuring = false) { value, error ->
        finishCommand(command, value, error)
      }
    }
  } catch (error: Exception) {
    Log.e("TrackPlayer", "Controller ${command.operation} failed", error)
    if (commandFailure == null) commandFailure = error
    finishCommand(command, null, error)
  }
}

private fun finishCommand(command: Command, result: SessionResult?, error: Throwable?) {
  completionCommands.remove(command)
  val failure = if (command.fence) commandFailure ?: error else error
  if (command.fence) commandFailure = null
  command.finish(result, failure)
}

private fun awaitResult(
  connection: Connection,
  result: ListenableFuture<SessionResult>,
  configuring: Boolean,
  complete: (SessionResult?, Throwable?) -> Unit,
) {
  result.addListener({
    if (attempt === connection) {
      val operation = if (configuring) "configuration" else "command"
      var value: SessionResult? = null
      var failure: Throwable? = null
      try {
        value = result.get()
        val code = value.resultCode
        if (code == SessionError.ERROR_SESSION_DISCONNECTED) {
          fail("Controller $operation disconnected")
          return@addListener
        }
        check(code == SessionResult.RESULT_SUCCESS) { "Session result: $code" }
      } catch (error: Exception) {
        if (configuring) {
          fail("Controller $operation failed", error)
          return@addListener
        }
        Log.e("TrackPlayer", "Controller $operation failed", error)
        failure = error
        if (commandFailure == null) commandFailure = error
      }
      complete(value, failure)
      commandRunning = false
      drainCommands()
    }
  }, mainExecutor)
}

