@ReactMethod
override fun awaitReady(promise: Promise) {
  controller.awaitReady { error ->
    if (error == null) promise.resolve(null)
    else promise.reject("player-not-ready", error.message, error)
  }
}

@ReactMethod
override fun awaitPlaybackCommands(promise: Promise) {
  controller.awaitPlaybackCommands { error ->
    if (error == null) promise.resolve(null)
    else promise.reject("player-command-failed", error.message, error)
  }
}

@ReactMethod(isBlockingSynchronousMethod = true)
override fun getPlayWhenReady(): Boolean = sync { it?.playWhenReady ?: false }

@ReactMethod
override fun getAudioSessionId(promise: Promise) {
  controller.enqueueResult("getAudioSessionId", completion = { result, error ->
    if (error != null) promise.reject("audio-session-unavailable", error.message, error)
    else promise.resolve(result?.extras?.getInt("audioSessionId", 0)?.takeIf { it > 0 })
  }) { mc ->
    mc.sendCustomCommand(
      SessionCommand(TrackPlayerPlaybackService.COMMAND_K1W1_AUDIO_SESSION, Bundle.EMPTY),
      Bundle.EMPTY,
    )
  }
}

